def restoreIpAddresses(digits):
    n = len(digits)
    res = []
    cur = []

    def go(i):
        k = len(cur)
        if k == 4:
            if i == n:
                res.append(cur[:])
            return
        rem = 4 - k
        if n - i < rem or n - i > 3 * rem:
            return
        for length in (1, 2, 3):
            if i + length > n:
                break
            part = digits[i:i + length]
            if length > 1 and part[0] == "0":
                break
            v = int(part)
            if v > 255:
                break
            cur.append(v)
            go(i + length)
            cur.pop()

    go(0)
    return res
